import math

def mean(xs):
    return sum(xs) / len(xs)

def sd(xs):
    m = mean(xs)
    return math.sqrt(sum((x - m) ** 2 for x in xs) / len(xs))

assert math.isclose(sd([1.0, 3.0]), 1.0)
print(sd([0.01, -0.02, 0.015, 0.005, -0.01]))
